-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "zhCN" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.mage.fire.Name"] = "火焰"
L["rm.era.mage.fire.Description"] = "火焰，适用于 10 至 60 级，在你有火焰天赋点而冰霜没有点数，或火焰是你的主天赋树时选用。以炎爆术开场（否则火球术）；气定神闲后使用炎爆术；拥有强化灼烧时，对能存活较久的目标用灼烧保持五层火焰易伤；用火焰冲击和灼烧收尾；火球术作为填充。与三个或更多敌人交战时：冲击波、烈焰风暴、魔爆术、冰锥术、暴风雪。提醒：对精英和长时间战斗在灼烧叠满五层时使用燃烧、护甲、奥术智慧、法力宝石、寒冰护体、法力护盾、唤醒、法术反制、解除次级诅咒、寒冰屏障、气定神闲。默认关闭：火焰冲击一就绪就穿插施放。"
L["rm.era.mage.fire.warcrafttavern.Name"] = "火焰（Warcraft Tavern）"
L["rm.era.mage.fire.warcrafttavern.Description"] = "依据 Warcraft Tavern 的火焰，是推荐的火焰内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。对精英和首领在拉怪时就使用燃烧，而不是等待灼烧叠层；以炎爆术开场；拥有强化灼烧时用灼烧保持五层；火球术作为填充；仅在移动时使用火焰冲击。怪群：先烈焰风暴，然后近身时使用魔爆术、冰锥术和冲击波，远距离时使用暴风雪。提醒与火焰内置循环相同。"
L["rm.era.mage.frost.Name"] = "冰霜"
L["rm.era.mage.frost.Description"] = "冰霜，适用于 1 至 60 级，也适用于奥术天赋，并且是法师在获得天赋前的默认循环。寒冰箭（4 级前为火球术）；怪物接近你时使用冰霜新星，团队副本首领除外；拥有强化奥术飞弹时，怪物接近你后使用奥术飞弹；与三个或更多敌人交战时使用冰锥术、魔爆术和暴风雪；移动且法力有余时使用火焰冲击；单刷时用火焰冲击和魔杖收掉普通怪物；法力耗尽时使用魔杖。提醒：护甲（单刷用冰甲术，组队用魔甲术，绝不替换你自己选择的护甲）、奥术智慧、制造和使用法力宝石、寒冰护体、法力护盾、唤醒、法术反制、解除次级诅咒、寒冰屏障、急速冷却、奥术强化和气定神闲。默认关闭：利用碎冰的烈焰风暴，以及用 1 级寒冰箭叠加深冬之寒。闪现术、变形术、放风筝和目标选择由你自己掌控。"
L["rm.era.mage.frost.icyveins.Name"] = "冰霜 AoE 刷怪（Icy Veins）"
L["rm.era.mage.frost.icyveins.Description"] = "依据 Icy Veins 的 AoE 刷怪指南进行暴风雪升级，单刷且拥有强化暴风雪时自动选择。与两个或更多敌人交战时：对怪群使用冰霜新星，冰霜新星冷却期间使用冰锥术，身边没有敌人后使用暴风雪，敌人在身边时使用魔爆术；单个目标使用寒冰箭，用火焰冲击和魔杖收尾。每次拉怪前施放法力护盾和寒冰护体。聚怪、闪现术和放风筝由你自己掌控。"
L["rm.forever.mage.arcane.Name"] = "奥术"
L["rm.forever.mage.arcane.Description"] = "当奥术是你的主要天赋树且已点出 11 点并学会奥术冲击后的奥术。单刷时以寒冰箭拉怪，组队时以奥术冲击拉怪；然后飞弹连射触发时使用奥术飞弹，节能施法时使用奥术冲击，奥术冲击叠满三层时使用奥术愤怒，在负担得起时（永久服中法力值是隐藏的）对精英叠加奥术冲击至四层、对其他目标叠加至两层，然后用霜火之箭、寒冰箭或火球术来触发飞弹连射，单刷且负担不起法术时使用魔杖。没有奥术愤怒时（较早的测试版设计）由火焰冲击消耗层数。移动时：火焰冲击。三个或更多敌人与你交战时：魔爆术。提醒：对精英使用气定神闲和奥术强化（奥术强化不再等待你的法力值降到一半），以及法师的常规维护提醒。"
L["rm.forever.mage.fire.Name"] = "火焰"
L["rm.forever.mage.fire.Description"] = "当火焰是你的主要天赋树且已点出 11 点（炎爆术所在层）后的火焰。对精英以炎爆术拉怪，否则用霜火之箭或火球术；然后在热力迸发叠满三层时使用炎爆术，寒冰指触发或目标被冻结时使用冰枪术（火焰/冰霜混合流派），火焰冲击冷却完毕即用，对精英使用灼烧保持五层火焰易伤，霜火之箭（40 级起）或火球术，单刷且负担不起法术时使用魔杖。移动时：火焰冲击或冰枪术。四个或更多敌人与你交战时：烈焰风暴、冲击波、魔爆术。只有在拥有强化灼烧后，灼烧才会开始叠层；近距离灼烧在你启用之前保持关闭。提醒：对精英使用燃烧和气定神闲，以及法师的常规维护提醒。"
L["rm.forever.mage.fire.icyveins.Name"] = "火焰升级（Icy Veins）"
L["rm.forever.mage.fire.icyveins.Description"] = "Icy Veins 不点强化灼烧的火焰升级天赋配置，是推荐的火焰内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。以炎爆术拉怪，用火焰冲击消耗火焰余波，怪物靠近时使用灼烧（永久服隐藏目标生命值，因此对低血量目标的收尾由你自己决定），然后是霜火之箭（40 级起）或火球术。范围伤害、移动、魔杖和提醒与火焰内置循环相同，但不含燃烧和气定神闲。"
L["rm.forever.mage.frost.Name"] = "冰霜"
L["rm.forever.mage.frost.Description"] = "冰霜，适用于 1 至 60 级，也是永久服法师在学会天赋法术前的默认循环（4 级学会寒冰箭之前为火球术）。以寒冰箭拉怪；然后在寒冰指触发或目标被冻结时使用冰枪术（寒冰箭仍在施放时也可使用，以取消或合并施法），深冬之寒叠满五层时使用冰锥术，飞弹连射触发时使用奥术飞弹，寒冰箭，单刷且负担不起寒冰箭时使用魔杖。移动时：冰枪术，否则火焰冲击。三个或更多敌人与你交战时：冰锥术；五个或更多时：暴风雪，或在有怪物贴身时使用魔爆术。包含 Warcraft Tavern 的烈焰风暴和魔爆术范围伤害打法，但默认关闭。提醒：奥术智慧、护甲（单刷用冰甲术或霜甲术，组队用魔甲术，绝不替换你已选择的护甲）、寒冰护体、法术反制、解除次级诅咒、怪物贴身时的冰霜新星、急速冷却。在永久服上生命值和法力值对插件隐藏，因此用火焰冲击收掉低血量目标、唤醒和寒冰屏障由你自己决定；闪现术、放风筝、变形术和法力宝石也由你自己掌控。"
L["rm.mop.mage.arcane.Name"] = "推荐"
L["rm.mop.mage.arcane.Description"] = "推荐奥术专精使用，适用于 10 至 90 级（在奥术专精中选用）。用奥术冲击叠加四层奥术充能；四层时，奥术飞弹！触发会用奥术飞弹消耗，没有触发时法力值低于 90% 就会施放奥术弹幕。法力值高于 95% 时会持续施放奥术冲击，这与模拟器的打法一致。绝不让奥术飞弹积压两次触发，在操控时间回溯之前施放奥术弹幕，面对两个或更多敌人时每四层充能施放一次奥术弹幕；五个敌人靠近时使用冰锥术和魔爆术。保持你的天赋炸弹，没有浮冰时移动中使用火焰冲击或冰枪术。提醒：四层充能且有触发时使用奥术强化和操控时间、霜甲术（54 级前为熔岩护甲）、奥术光辉、法术反制、法力宝石、镜像、寒冰护体、浮冰、能量符文或祈愿。时间扭曲、法术吸取和气定神闲为关闭状态；能量符文仍需你手动放置。"
L["rm.mop.mage.arcane.icyveins.Name"] = "四层充能时奥术弹幕（Icy Veins）"
L["rm.mop.mage.arcane.icyveins.Description"] = "指南的奥术规则（Icy Veins、Wowhead、Method、wowtbc.gg），作为推荐奥术内置循环的替代：四层奥术充能时，有触发就用奥术飞弹，否则无论法力值多少都用奥术弹幕；奥术飞弹仅在四层充能时使用。其余所有内容（操控时间、炸弹、范围伤害、移动、提醒）与推荐的循环相同，只是奥术强化会在四层充能时建议使用，而不等待触发。默认关闭：启用它并禁用推荐的奥术内置循环，或提高它的优先级。"
L["rm.mop.mage.fire.Name"] = "推荐"
L["rm.mop.mage.fire.Description"] = "推荐火焰专精使用，适用于 10 至 90 级（在火焰专精中选用）。以读条炎爆术开场，然后用炼狱冲击（24 级前为火焰冲击）把热力迸发变成炎爆术！触发，除非燃烧即将冷却完毕，否则立即施放；然后在你施放火球术的同时等待下一次热力迸发。燃烧会在炎爆术之后、目标身上同时有点燃和炎爆术的灼烧效果时立即施放；插件无法看到点燃的大小，因此点燃较弱时请自行判断。保持你的天赋炸弹，有两个或更多敌人与你交战时用炼狱冲击扩散，五个敌人靠近时使用冰锥术和魔爆术，移动时使用灼烧。提醒：熔岩护甲、气定神闲、两种触发都在时使用操控时间、法力宝石、奥术光辉、法术反制、镜像、寒冰护体、浮冰、祈愿或能量符文。龙息术、时间扭曲和法术吸取为关闭状态。"
L["rm.mop.mage.fire.icyveins.Name"] = "保留炎爆术！（Icy Veins）"
L["rm.mop.mage.fire.icyveins.Description"] = "Icy Veins、Method 和 wowtbc.gg 的火焰打法，作为推荐火焰内置循环的替代：炎爆术！触发会一直保留，直到热力迸发也出现，然后与你的火球术一起施放，只有在即将过期时才单独使用。其余与推荐的循环相同。默认关闭：启用它并禁用推荐的火焰内置循环，或提高它的优先级。"
L["rm.mop.mage.frost.Name"] = "推荐"
L["rm.mop.mage.frost.Description"] = "冰霜，适用于 10 至 90 级（在冰霜专精中选用）。两层寒冰指时使用冰枪术，冰冷智慧触发时使用霜火之箭，你的天赋炸弹，寒冰宝珠，一层寒冰指时使用冰枪术，寒冰箭；87 级起，操控时间还有不到 10 秒就绪时会保留触发留给它。两个或更多敌人时：寒冰宝珠，敌人靠近时使用冰锥术和魔爆术，四个敌人站着不动时使用暴风雪。没有浮冰时移动中使用冰枪术和火焰冲击。提醒：水元素、对首领以外的目标使用冰冻术（自行放置）、与操控时间配合使用冰冷血脉、冰冷血脉期间两层寒冰指时使用操控时间、霜甲术（54 级前为熔岩护甲）、法力宝石、奥术光辉、法术反制、镜像、寒冰护体、浮冰、祈愿或能量符文。急速冷却、气定神闲、时间扭曲和法术吸取为关闭状态。"
L["rm.mop.mage.unspecialized.Name"] = "选择专精前"
L["rm.mop.mage.unspecialized.Description"] = "适用于 1 至 9 级，以及尚未选择专精的法师。霜火之箭，用火焰冲击收尾或在移动时使用，学会后在移动时使用冰枪术，三个或更多敌人处于近战范围时使用魔爆术。提醒：怪物接近你时使用冰霜新星、法术反制，以及达到相应等级后的熔岩护甲和奥术光辉。10 级选择专精后会切换到该专精的内置循环。"
L["rm.retail.mage.arcane.Name"] = "暴雪战斗辅助"
L["rm.retail.mage.arcane.Description"] = "推荐奥术专精使用。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议；你施法或引导时它会等待。同时提醒战斗辅助留给你处理的部分：战斗中的奥术涌动、脱战时的奥术智慧、对可打断的施法使用法术反制、战斗中一就绪就使用的棱光护体，以及战斗中你的种族冷却技能。敌人的施法在战斗中是隐藏的，因此法术反制只在游戏显示它们的场合亮起；生命值在正式服中是隐藏的，因此寒冰屏障和其他紧急按钮由你自己决定。镜像、操控时间、闪现术和饰品仍由你自己掌控。"
L["rm.retail.mage.arcane.guide.Name"] = "参考（Icy Veins 和 SimulationCraft）"
L["rm.retail.mage.arcane.guide.Description"] = "仅供参考，默认关闭：指南中的奥术优先级。在至暗之夜的战斗中，奥术齐射和节能施法对插件隐藏（只有奥术充能仍然可见），因此它无法在战斗中运行；法力值在正式服中是隐藏的，所以低法力时的唤醒由你自己决定；可以阅读它，或复制后自行试验。以奥术冲击拉怪。日怒：奥术齐射低于 12 层且节能施法触发时使用奥术飞弹，奥术之魂之外使用棱彩飞弹，四层奥术充能且奥术齐射达到 12 层并有节能施法或奥术齐射达到 25 层时，或奥术之魂期间无论充能多少，使用奥术弹幕，棱彩飞弹，奥术充能少于三层时使用奥术宝珠，面对三个敌人或没有奥术充能时使用奥术脉冲，奥术冲击。疾咒师（已学会裂解巫术）：棱彩飞弹，面对成群敌人时使用奥术宝珠，奥术齐射达到 20 层时使用奥术弹幕（面对两个或更多敌人时仅在四层奥术充能时使用），奥术齐射低于 15 层且节能施法触发时使用奥术飞弹，奥术充能少于三层时使用奥术宝珠和奥术脉冲（奥术涌动期间不用奥术脉冲），奥术冲击。无法施放奥术冲击时使用奥术弹幕。提醒：奥术涌动、在奥术涌动期间或离奥术涌动还早时，于奥术弹幕或棱彩飞弹之后使用大法师之触、没有奥术充能时在奥术弹幕之后使用气定神闲，以及战斗辅助内置循环中的提醒。"
L["rm.retail.mage.fire.Name"] = "暴雪战斗辅助"
L["rm.retail.mage.fire.Description"] = "推荐火焰专精使用。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议；你施法或引导时它会等待。同时提醒战斗辅助留给你处理的部分：战斗中的燃烧、脱战时的奥术智慧、对可打断的施法使用法术反制、战斗中一就绪就使用的烈焰护体，以及战斗中你的种族冷却技能。敌人的施法在战斗中是隐藏的，因此法术反制只在游戏显示它们的场合亮起；生命值在正式服中是隐藏的，因此寒冰屏障和其他紧急按钮由你自己决定。"
L["rm.retail.mage.fire.guide.Name"] = "参考（Icy Veins、Wowhead 和 SimulationCraft）"
L["rm.retail.mage.fire.guide.Description"] = "仅供参考，默认关闭：指南中的火焰优先级。炽热连击、热力迸发、火焰冲撞和火焰冲击的充能在至暗之夜的战斗中是隐藏的，因此它无法在战斗中运行。在施法即将完成时使用火焰冲击，把热力迸发转为炽热连击；以炎爆术拉怪。过热高温触发时使用炎爆术（四个或更多敌人时改用烈焰风暴），流星，炽热连击触发时使用炎爆术，燃烧期间热力迸发触发时使用火焰冲击，火焰冲撞触发时使用炎爆术，热能闪光触发或移动中使用灼烧，热力迸发触发时使用火焰冲击，然后是霜火之箭或火球术。提醒：读条法术即将完成时使用燃烧、烈焰护体以及功能性提醒。等待纵火者阶段结束，以及让流星落在燃烧期间的时机仍由你自己掌控。"
L["rm.retail.mage.frost.Name"] = "暴雪战斗辅助"
L["rm.retail.mage.frost.Description"] = "推荐冰霜专精使用。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议；你施法或引导时它会等待。同时提醒战斗辅助留给你处理的部分：已学会天赋但没有水元素时使用召唤水元素、脱战时的奥术智慧、对可打断的施法使用法术反制、战斗中一就绪就使用的寒冰护体，以及战斗中你的种族冷却技能。敌人的施法在战斗中是隐藏的，因此法术反制只在游戏显示它们的场合亮起；生命值在正式服中是隐藏的，因此寒冰屏障和其他紧急按钮由你自己决定。"
L["rm.retail.mage.frost.guide.Name"] = "参考（Icy Veins 和 SimulationCraft）"
L["rm.retail.mage.frost.guide.Description"] = "仅供参考，默认关闭：指南中针对各英雄天赋的冰霜优先级。触发效果、冻结层数和冷却在至暗之夜的战斗中是隐藏的，因此它无法在战斗中运行。以霜火之箭或寒冰箭拉怪。霜火（已学会霜火之箭）：冰川尖刺就绪即用，一到两个敌人时使用彗星风暴，冰冷智慧触发且没有热能真空时使用冰风暴，两层寒冰指时使用冰枪术，冰霜射线，寒冰宝珠，三个敌人且冰冻之雨触发时使用暴风雪，有热能真空时寒冰指触发或冻结达到十二层时使用冰枪术，冰风暴，五个敌人时使用寒冰新星或冰锥术，然后是冰川尖刺或霜火之箭。疾咒师：彗星风暴，冰冷智慧触发时使用冰风暴，两层寒冰指时使用冰枪术，寒冰宝珠，冰川尖刺就绪即用，冰冻之雨触发时使用暴风雪，寒冰指触发或冻结达到六层时使用冰枪术，冰霜射线，冰风暴，四个敌人时使用寒冰新星或冰锥术，七个敌人时使用暴风雪，然后是冰川尖刺或寒冰箭。移动中使用冰枪术。提醒：召唤水元素、寒冰护体以及功能性提醒。"
L["rm.retail.mage.initial.Name"] = "暴雪战斗辅助"
L["rm.retail.mage.initial.Description"] = "推荐在你选择专精之前使用（此时游戏报告的是法师的初始专精）。高亮暴雪战斗辅助建议的下一个法术，这是在至暗之夜的战斗中游戏仍允许插件读取的唯一循环建议；你施法或引导时它会等待。同时包含所有法师内置循环共用的提醒，每一项在你学会对应法术后生效。当你在 10 级选择专精后，该专精的内置循环会接管。"
L["rm.sod.mage.arcane.Name"] = "奥术（探索赛季）"
L["rm.sod.mage.arcane.Description"] = "探索赛季的奥术伤害，在奥术是你的主天赋树且铭刻了奥术冲击时选用。飞弹连射触发时使用奥术飞弹；奥术冲击叠满四层时使用奥术弹幕；安全时使用怨火之箭，但怨火层数达到四层或以上时绝不使用；活体烈焰冷却完毕即用；奥术冲击作为填充。移动时使用奥术弹幕和火焰冲击；对怪群使用活体烈焰和魔爆术。提醒：对精英和长时间战斗使用奥术强化、配合奥术强化或在移动时使用气定神闲、冰冷血脉、急速冷却以及其他法师提醒。"
L["rm.sod.mage.fire.Name"] = "火焰（探索赛季）"
L["rm.sod.mage.fire.Description"] = "探索赛季的火焰，适用于 1 至 60 级，也是该赛季法师的默认循环。使用你已铭刻的符文：法术连击触发时立即使用炎爆术；对能存活较久的目标保持活动炸弹；拥有强化灼烧时，在火焰易伤低于两层或即将消失时使用灼烧；活体烈焰冷却完毕即用；火焰易伤达到五层时使用怨火之箭，但怨火层数达到四层或以上时绝不使用（第五层会杀死你）；霜火之箭，否则火球术。移动时使用活动炸弹、活体烈焰和火焰冲击；对怪群使用活体烈焰、活动炸弹、冲击波、冰锥术、烈焰风暴和暴风雪。提醒：过热时使用火焰冲击、燃烧、冰冷血脉和急速冷却、熔岩护甲或其他护甲、奥术智慧、法力宝石、寒冰护体、法力护盾、唤醒、法术反制、解除诅咒、寒冰屏障。把活动炸弹扩散到多个目标由你自己掌控。"
L["rm.sod.mage.frost.Name"] = "冰霜（探索赛季）"
L["rm.sod.mage.frost.Description"] = "探索赛季的冰霜，10 级起，在冰霜是你的主天赋树时选用。你的冻结达到三层或以上时，寒冰指用于冰枪术，否则用于深度冻结；冰冷智慧触发时使用怨火之箭，其他情况下在安全时使用，但怨火层数达到四层或以上时绝不使用；铭刻后使用活动炸弹和活体烈焰；法术冰霜箭，否则霜火之箭，再否则寒冰箭。移动时使用冰枪术、寒冰宝珠、活动炸弹和火焰冲击；对怪群使用寒冰宝珠、活体烈焰、活动炸弹、暴风雪和冰锥术。提醒：寒冰宝珠、冰冷血脉、急速冷却、护甲、法力宝石以及其他法师提醒。在箭类法术命中时预先排队下一个法术由你自己掌控。"
L["rm.sod.mage.frost.warcrafttavern.Name"] = "冰霜，火焰符文（探索赛季，Warcraft Tavern）"
L["rm.sod.mage.frost.warcrafttavern.Description"] = "Warcraft Tavern 第 4 阶段使用火焰符文的冰霜天赋，是推荐的探索赛季冰霜内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。以炎爆术开场；法术连击触发时使用炎爆术；保持活动炸弹；拥有强化灼烧时用灼烧叠到五层；怨火之箭仅在冰冷智慧触发时使用，且怨火层数达到四层或以上时绝不使用；霜火之箭作为填充。移动时使用活动炸弹和火焰冲击；对怪群使用活动炸弹、冰锥术和暴风雪。提醒：过热时使用火焰冲击、冰冷血脉期间使用寒冰宝珠、冰冷血脉、急速冷却以及其他法师提醒。"
L["rm.sod.mage.healer.Name"] = "治疗（探索赛季）"
L["rm.sod.mage.healer.Description"] = "探索赛季的法师治疗，铭刻了再生或群体再生时选用。友方目标时：生命值低于一半时使用时光倒转和凝时恩护，你的时光道标缺失时使用再生，群体再生，时空畸体。敌对目标时，使用能治疗你的道标目标的伤害法术：冰霜治疗者使用法术冰霜箭，否则飞弹连射触发时使用奥术飞弹，奥术冲击达到两层时使用奥术弹幕，安全时使用怨火之箭（怨火层数达到四层或以上时绝不使用）以及奥术冲击。提醒：奥术强化、气定神闲、寒冰宝珠以及其他法师提醒。默认关闭：对怪群使用魔爆术，以及冰霜治疗者的冰枪术和深度冻结。引导群体再生时，下一个法术已经显示，因此你可以立即取消它（它的直接治疗量很小）。治疗谁由你自己掌控。"
L["rm.tbc.mage.arcane.Name"] = "奥术"
L["rm.tbc.mage.arcane.Description"] = "奥术，在奥术是你的主天赋树时选用。64 级前：奥术飞弹，法力值不足时使用寒冰箭。64 级起：爆发期间（奥术强化、嗜血或法力值高于 35%）使用奥术冲击，否则叠加三层奥术冲击，然后使用寒冰箭直到层数即将消失。三个或更多敌人时使用魔爆术和冰锥术。提醒包括奥术强化、气定神闲、法力宝石和唤醒。"
L["rm.tbc.mage.fire.icyveins.Name"] = "火焰（Icy Veins）"
L["rm.tbc.mage.fire.icyveins.Description"] = "依据 Icy Veins 的火焰，在火焰是你的主天赋树时选用。学会炎爆术后用它开怪，强化灼烧保持五层火焰易伤，火球术作为填充，火焰冲击用于移动时；三个或更多敌人时使用冲击波、龙息术和烈焰风暴。提醒：熔岩护甲、法师护甲或冰甲术，目标生命值低于 20% 时使用燃烧，法力宝石、唤醒以及共用的法师辅助技能。"
L["rm.tbc.mage.fire.wowhead.Name"] = "火焰（Wowhead）"
L["rm.tbc.mage.fire.wowhead.Description"] = "依据 Wowhead 和 模拟器 的火焰。与 Icy Veins 火焰内置循环相同，但只要你站立不动，火焰冲击一就绪就会穿插施放（伤害更高，耗蓝更多），并以火球术而非炎爆术开怪。它是推荐的 Icy Veins 火焰内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。"
L["rm.tbc.mage.frost.Name"] = "冰霜"
L["rm.tbc.mage.frost.Description"] = "冰霜，适用于 1 至 70 级，也是法师在获得天赋前的默认循环。寒冰箭（4 级前为火球术），有敌人攻击你时使用冰霜新星，与三个或更多敌人交战时使用冰锥术配合暴风雪或魔爆术，对冻结的目标以及移动时使用冰枪术，法力耗尽时使用魔杖。提醒：护甲、奥术智慧、法力宝石、唤醒、法术反制、法术偷取、寒冰护体、冰冷血脉、急速冷却和水元素。闪现术、寒冰屏障、放风筝和目标选择由你自己掌控。"
